#!/usr/bin/env python3
"""Expose QEMU's serial Unix socket on TCP 6665, replaying recent output."""
import selectors
import socket
import sys
import time

LISTEN_ADDR = ("127.0.0.1", 6665)
SERIAL_PATH = "/tmp/alpine-serial.sock"
MAX_BUFFER = 256 * 1024

buffer = bytearray()
client = None
sel = selectors.DefaultSelector()


def open_serial():
    while True:
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        try:
            s.connect(SERIAL_PATH)
            s.setblocking(False)
            return s
        except OSError:
            s.close()
            time.sleep(0.2)


def drop_client():
    global client
    if client is not None:
        try:
            sel.unregister(client)
        except Exception:
            pass
        try:
            client.close()
        except Exception:
            pass
        client = None


listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
listener.bind(LISTEN_ADDR)
listener.listen(5)
listener.setblocking(False)
sel.register(listener, selectors.EVENT_READ, "listener")

serial_sock = open_serial()
sel.register(serial_sock, selectors.EVENT_READ, "serial")
print("relay ready on %s:%d" % LISTEN_ADDR, flush=True)

while True:
    for key, _mask in sel.select(timeout=1.0):
        if key.data == "listener":
            conn, _addr = listener.accept()
            conn.setblocking(False)
            drop_client()
            client = conn
            sel.register(conn, selectors.EVENT_READ, "client")
            try:
                conn.sendall(buffer)
            except OSError:
                drop_client()
        elif key.data == "serial":
            try:
                data = serial_sock.recv(65536)
            except OSError:
                data = b""
            if not data:
                print("serial connection closed", flush=True)
                sys.exit(1)
            buffer.extend(data)
            if len(buffer) > MAX_BUFFER:
                del buffer[: len(buffer) - MAX_BUFFER]
            if client is not None:
                try:
                    client.sendall(data)
                except OSError:
                    drop_client()
        elif key.data == "client":
            try:
                data = client.recv(65536)
            except OSError:
                data = b""
            if not data:
                drop_client()
            else:
                try:
                    serial_sock.sendall(data)
                except OSError:
                    pass

